const app=document.querySelector("#app"),toastRegion=document.querySelector("#toast-region");
const json=async path=>{const response=await fetch(path);if(!response.ok)throw new Error(`Falha ao carregar ${path}`);return response.json()};
const [data,locales,version,story,videoManifest,flightManifest,engineeringData,crewOps]=await Promise.all([json("./data/game.json"),json("./data/locales.json?v=5.0.0"),json("./version.json?v=5.0.0"),json("./data/story.json?v=5.0.0"),json("./assets/video/video-manifest.json?v=5.0.0"),json("./assets/video/flight-manifest.json?v=5.0.0"),json("./data/engineering.json?v=5.0.0"),json("./data/crew-operations.json?v=5.0.0")]);
let locale=localStorage.getItem("lh-locale")||"pt-BR",lastState=null,autosaveTimer=null;
const t=key=>locales[locale]?.[key]||locales["pt-BR"][key]||key;
const esc=value=>String(value??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const pct=n=>`${Math.round(clamp(n))}%`,money=n=>`${Math.round(n)} bi`;
const initial=recalculate(createInitialState(),data,crewOps);
const store=createStore(initial,s=>recalculate(s,data,crewOps));

function toast(message,type="ok"){const el=document.createElement("div");el.className=`toast ${type}`;el.textContent=message;toastRegion.append(el);setTimeout(()=>el.remove(),3200)}
function audioCue(type="select"){
  if(!store.getState().profile.audio)return;
  try{const Ctx=window.AudioContext||window.webkitAudioContext,ctx=new Ctx(),o=ctx.createOscillator(),g=ctx.createGain();o.type="sine";o.frequency.value=type==="alarm"?190:type==="success"?620:420;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17)}catch{}
}
function applyAccessibility(state){const a=state.profile.accessibility;document.body.classList.toggle("reduce-motion",a.reduceMotion);document.body.classList.toggle("high-contrast",a.highContrast);document.body.classList.toggle("large-text",a.largeText);document.body.classList.toggle("colorblind",a.colorblind)}
function logTime(hours){const day=Math.floor(hours/24);return `D+${String(day).padStart(3,"0")}`}

function menu(){const s=store.getState(),hasSave=!!localStorage.getItem("lh-has-save");app.innerHTML=`
  <main class="splash"><section class="splash-content">
    <div class="eyebrow">GSEA · PROJECT HAVEN</div><h1><span>GLOBAL SPACE AGENCY SIMULATOR</span>LAST<br>HORIZON</h1>
    <p class="lead">A Terra está ficando sem tempo. Projete a ARK-01, lidere sua tripulação e decida quais riscos a humanidade carregará até outro mundo.</p>
    <div class="menu-buttons">
      <button class="primary mission-start" data-action="new"><span>INICIAR MISSÃO</span><small>campanha narrativa completa</small></button>
      <button data-action="continue" ${hasSave?"":"disabled"}>${t("continue")}</button>
      <button data-action="expedition">${t("expedition")}</button>
      <button data-action="simulator">${t("simulator")}</button>
      <button data-action="saves">${t("saves")}</button><button data-action="settings">${t("settings")}</button>
    </div><div class="build-tag">${t("build")} ${esc(version.version)} · OFFLINE · ${esc(version.build)}</div>
  </section></main>`;
  bindMenu();
}

function bindMenu(){
  one("[data-action=new]","click",()=>profileModal("campaign"));
  one("[data-action=expedition]","click",()=>profileModal("expedition"));
  one("[data-action=simulator]","click",()=>{const s=createInitialState(`SIM-${Date.now()}`,"simulator");s.ui.route="simulator";store.replace(s);router.navigate("simulator")});
  one("[data-action=continue]","click",async()=>{try{store.replace(await loadGame("autosave"));locale=store.getState().profile.language||locale;router.navigate(store.getState().ui.route||"agency")}catch(e){toast(e.message,"error")}});
  one("[data-action=saves]","click",saveModal);one("[data-action=settings]","click",settingsModal);
}

function profileModal(mode){modal(`
  <div class="eyebrow">GSEA · CREDENCIAL DE DIREÇÃO</div><h2>${mode==="expedition"?"Configurar expedição":"Assumir o PROJECT HAVEN"}</h2>
  <p class="muted">Sua identidade, dificuldade e seed serão registradas no histórico da missão.</p>
  <div class="form-row"><div class="field"><label for="director">Nome do diretor</label><input id="director" maxlength="36" value="Alex Silva"></div><div class="field"><label for="difficulty">Dificuldade</label><select id="difficulty"><option value="story">Narrativa</option><option value="standard" selected>Padrão</option><option value="simulation">Simulação</option><option value="hardcore">Sobrevivência</option></select></div></div>
  <div class="field" style="margin-top:.8rem"><label for="seed">Seed reproduzível</label><input id="seed" value="${mode==="expedition"?`EXP-${new Date().toISOString().slice(0,10)}`:"HAVEN-2047"}"></div>
  <div class="card-actions"><button data-close>${t("back")}</button><button class="primary" data-start>${t("confirm")}</button></div>`,()=>{
    one("[data-start]","click",()=>{const name=document.querySelector("#director").value.trim()||"Diretor(a)",seed=document.querySelector("#seed").value.trim()||"HAVEN-2047",difficulty=document.querySelector("#difficulty").value;const next=createInitialState(seed,mode);next.profile.directorName=name;next.profile.difficulty=difficulty;next.profile.language=locale;if(mode==="expedition"){const mod=(next.meta.rngState%25)-12;next.economy.available+=mod;next.agency.support=clamp(45-mod/2);next.logs.events[0].message=`Expedição procedural iniciada com seed ${seed}. Modificador orçamentário: ${mod}.`}store.replace(next);closeModal();router.navigate("prologue");toast("Diretoria confirmada. O briefing vai começar.");audioCue("success")});
  });
}

